var PAGE5 = 1e3;
async function fetchAll5(table, orderBy = "created_at") {
  const out = [];
  for (let from = 0; ; from += PAGE5) {
    const { data, error } = await supabase.from(table).select("*").order(orderBy, { ascending: true }).range(from, from + PAGE5 - 1);
    if (error) throw new Error(error.message);
    const rows = data ?? [];
    out.push(...rows);
    if (rows.length < PAGE5) break;
  }
  return out;
}
